import android.provider.Settings;
public class OverlayService extends Service {
 android.animation.AnimatorSet pulse;public static OverlayService active;WindowManager wm;View bubble,dropTarget;boolean dragging;LinearLayout panel,actions;WebView web;WindowManager.LayoutParams bubbleParams;float startX,startY;int oldX,oldY;
 @Override public void onCreate(){super.onCreate();active=this;wm=(WindowManager)getSystemService(WINDOW_SERVICE);}
 @Override public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&"stop".equals(intent.getAction())){stopSelf();getSharedPreferences("amora",0).edit().putBoolean("overlayEnabled",false).apply();return START_NOT_STICKY;}if(!Settings.canDrawOverlays(this)){stopSelf();return START_NOT_STICKY;}
 PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,OverlayService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=NativeBridge.notification(this,"lilith-bubble","Lilith está por perto","Toque na amorinha para conversar.",stop);if(Build.VERSION.SDK_INT>=34)startForeground(101,n,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(101,n);
 if(bubble==null){ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.amora_icon);icon.setContentDescription("Abrir Lilith");icon.setPadding(dp(7),dp(7),dp(7),dp(7));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(Color.rgb(249,240,249));bg.setShape(android.graphics.drawable.GradientDrawable.OVAL);icon.setBackground(bg);icon.setClipToOutline(true);bubble=icon;bubbleParams=new WindowManager.LayoutParams(dp(58),dp(58),WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);bubbleParams.setTitle("Amora Lilith Bubble");bubbleParams.gravity=Gravity.TOP|Gravity.LEFT;bubbleParams.x=getResources().getDisplayMetrics().widthPixels-dp(74);bubbleParams.y=dp(200);wm.addView(bubble,bubbleParams);bubble.setOnTouchListener((v,e)->{switch(e.getActionMasked()){
 case MotionEvent.ACTION_DOWN:startX=e.getRawX();startY=e.getRawY();oldX=bubbleParams.x;oldY=bubbleParams.y;dragging=false;return true;
 case MotionEvent.ACTION_MOVE:if(Math.hypot(e.getRawX()-startX,e.getRawY()-startY)>dp(10)){dragging=true;showDropTarget();}bubbleParams.x=Math.max(0,Math.min(getResources().getDisplayMetrics().widthPixels-dp(58),oldX+(int)(e.getRawX()-startX)));bubbleParams.y=Math.max(0,Math.min(getResources().getDisplayMetrics().heightPixels-dp(58),oldY+(int)(e.getRawY()-startY)));wm.updateViewLayout(bubble,bubbleParams);if(dropTarget!=null)dropTarget.setAlpha(overDrop(e.getRawX(),e.getRawY())?1f:.68f);return true;
 case MotionEvent.ACTION_UP:boolean dismiss=dragging&&overDrop(e.getRawX(),e.getRawY());hideDropTarget();if(dismiss){getSharedPreferences("amora",0).edit().putBoolean("overlayEnabled",false).apply();NativeBridge.event("info","Bolinha desativada. Você pode ativar de novo em Meu app.");stopSelf();}else if(!dragging){if(panel!=null&&panel.getVisibility()==View.VISIBLE)hidePanel();else showPanel();}return true;
 case MotionEvent.ACTION_CANCEL:hideDropTarget();return true;
 }return false;});}
 return START_STICKY;}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 public static void speaking(boolean on){if(active==null||active.bubble==null)return;OverlayService s=active;if(s.pulse!=null)s.pulse.cancel();if(on){android.animation.ObjectAnimator x=android.animation.ObjectAnimator.ofFloat(s.bubble,"scaleX",1f,1.14f,1f),y=android.animation.ObjectAnimator.ofFloat(s.bubble,"scaleY",1f,1.14f,1f);x.setRepeatCount(-1);y.setRepeatCount(-1);s.pulse=new android.animation.AnimatorSet();s.pulse.playTogether(x,y);s.pulse.setDuration(900);s.pulse.start();}else{s.bubble.setScaleX(1);s.bubble.setScaleY(1);}}
 boolean overDrop(float x,float y){return Math.abs(x-getResources().getDisplayMetrics().widthPixels/2f)<dp(65)&&y>getResources().getDisplayMetrics().heightPixels-dp(145);}
 void showDropTarget(){if(dropTarget!=null){dropTarget.setVisibility(View.VISIBLE);return;}TextView target=new TextView(this);target.setText("×\nSolte para remover");target.setTextColor(Color.WHITE);target.setTextSize(18);target.setGravity(Gravity.CENTER);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(0xe631203e);bg.setCornerRadius(dp(28));bg.setStroke(dp(1),0xffb99bce);target.setBackground(bg);target.setContentDescription("Remover bolinha");dropTarget=target;WindowManager.LayoutParams p=new WindowManager.LayoutParams(dp(164),dp(96),WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,PixelFormat.TRANSLUCENT);p.setTitle("Amora Remove Bubble");p.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL;p.y=dp(24);wm.addView(target,p);}
 void hideDropTarget(){if(dropTarget!=null)dropTarget.setVisibility(View.GONE);}
 public static void showPanel(){if(active==null)return;if(active.getSharedPreferences("amora",0).getBoolean("biometricEnabled",false)){active.startActivity(new Intent(active,MainActivity.class).setAction("amora.unlockOverlay").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));}else active.openPanel();}
 public static void showVerifiedPanel(){if(active!=null)active.openPanel();}
 public static void hidePanel(){if(active!=null&&active.panel!=null){android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)active.getSystemService(INPUT_METHOD_SERVICE);keyboard.hideSoftInputFromWindow(active.panel.getWindowToken(),0);active.panel.clearFocus();active.panel.setVisibility(View.GONE);}}
 void refreshActions(){if(actions==null)return;actions.removeAllViews();try{org.json.JSONArray list=new org.json.JSONArray(getSharedPreferences("amora",0).getString("overlayActions","[\"lilith\",\"chat\",\"apps\"]"));for(int i=0;i<list.length();i++){String route=list.getString(i);Button button=new Button(this);button.setText(route.equals("lilith")?"Lilith":route.equals("chat")?"Conversa":route.equals("camera")?"Câmera":"Apps");button.setAllCaps(false);button.setTextSize(12);button.setTextColor(Color.rgb(230,210,245));button.setBackgroundColor(Color.TRANSPARENT);button.setOnClickListener(v->{if(route.equals("lilith")){NativeBridge.event("route","lilith");}else{startActivity(new Intent(this,MainActivity.class).putExtra("route",route).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));hidePanel();}});actions.addView(button,new LinearLayout.LayoutParams(0,dp(48),1));}}catch(Exception ignored){}}
 void openPanel(){if(panel==null){panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);android.graphics.drawable.GradientDrawable glass=new android.graphics.drawable.GradientDrawable();glass.setColor(0xdf241c30);glass.setCornerRadii(new float[]{dp(28),dp(28),dp(28),dp(28),0,0,0,0});glass.setStroke(dp(1),0x60c8a6df);panel.setBackground(glass);panel.setClipToOutline(true);panel.setPadding(dp(8),dp(8),dp(8),0);LinearLayout toolbar=new LinearLayout(this);Button app=new Button(this);app.setText("Abrir Amora");app.setOnClickListener(v->{startActivity(new Intent(this,MainActivity.class).putExtra("route","home").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));hidePanel();});Button close=new Button(this);close.setText("Recolher");close.setOnClickListener(v->hidePanel());toolbar.addView(app,new LinearLayout.LayoutParams(0,dp(45),1));toolbar.addView(close,new LinearLayout.LayoutParams(0,dp(45),1));for(int j=0;j<toolbar.getChildCount();j++){Button t=(Button)toolbar.getChildAt(j);t.setTextColor(Color.rgb(238,220,250));t.setTextSize(12);t.setAllCaps(false);t.setBackgroundColor(Color.TRANSPARENT);}panel.addView(toolbar);actions=new LinearLayout(this);panel.addView(actions);refreshActions();web=AmoraWeb.create(this,"?panel=lilith&overlay=1");web.setBackgroundColor(Color.TRANSPARENT);panel.addView(web,new LinearLayout.LayoutParams(-1,0,1));WindowManager.LayoutParams params=new WindowManager.LayoutParams(getResources().getDisplayMetrics().widthPixels-dp(16),(int)(getResources().getDisplayMetrics().heightPixels*.66),WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);params.setTitle("Amora Lilith Panel");params.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL;params.softInputMode=WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE;wm.addView(panel,params);}panel.setVisibility(View.VISIBLE);panel.requestFocus();if(web!=null){NativeBridge.flush(web);web.evaluateJavascript("window.dispatchEvent(new CustomEvent('amora-native',{detail:{route:'lilith'}}))",null);}}
 @Override public void onDestroy(){active=null;if(pulse!=null)pulse.cancel();if(dropTarget!=null)wm.removeView(dropTarget);if(bubble!=null)wm.removeView(bubble);if(panel!=null)wm.removeView(panel);if(web!=null)AmoraWeb.destroy(web);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
